query:
CREATE TABLE `subscription_plans` (
	`id` int AUTO_INCREMENT NOT NULL,
	`name` varchar(100) NOT NULL,
	`tier` varchar(50) NOT NULL,
	`price` int NOT NULL,
	`maxBranches` int,
	`stripePriceId` varchar(255),
	`description` text,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `subscription_plans_id` PRIMARY KEY(`id`),
	CONSTRAINT `subscription_plans_tier_unique` UNIQUE(`tier`)
);
CREATE TABLE `upload_history` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`fileName` varchar(255) NOT NULL,
	`recordCount` int NOT NULL DEFAULT 0,
	`uploadDate` timestamp NOT NULL DEFAULT (now()),
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `upload_history_id` PRIMARY KEY(`id`)
);
ALTER TABLE `users` ADD `uploadCount` int DEFAULT 0 NOT NULL;
ALTER TABLE `users` ADD `subscriptionTier` varchar(50) DEFAULT 'free' NOT NULL;
ALTER TABLE `users` ADD `subscriptionStatus` varchar(50) DEFAULT 'inactive' NOT NULL;
ALTER TABLE `users` ADD `stripeCustomerId` varchar(255);
ALTER TABLE `users` ADD `stripeSubscriptionId` varchar(255);
ALTER TABLE `users` ADD `subscriptionExpiryDate` timestamp;

